<?php
error_reporting(0); if (!isset($_SESSION["mikhmon"])) { header("Location:../admin.php?id=login"); exit; }
$name=$_GET['profile']; $rows=$API->comm('/ppp/profile/print',array('?name'=>$name)); $p=isset($rows[0])?$rows[0]:array();
if(!$p){echo '<div class="card"><div class="card-body">Profil tidak ditemukan.</div></div>';return;}
if(isset($_POST['save'])){$API->comm('/ppp/profile/set',array('.id'=>$p['.id'],'name'=>trim($_POST['name']),'local-address'=>$_POST['local-address'],'remote-address'=>$_POST['remote-address'],'rate-limit'=>$_POST['rate-limit'],'dns-server'=>$_POST['dns-server'],'comment'=>$_POST['comment']));echo "<script>window.location='./?ppp=profiles&session=".$session."'</script>";exit;}
function pv($k,$p){return htmlspecialchars(isset($p[$k])?$p[$k]:'',ENT_QUOTES);}
?><div class="row"><div class="col-8"><div class="card box-bordered"><div class="card-header"><h3><i class="fa fa-edit"></i> <?= $_ppp_profiles ?></h3></div><div class="card-body"><form method="post"><a class="btn bg-warning" href="./?ppp=profiles&session=<?= $session ?>"><?= $_close ?></a> <button class="btn bg-primary" name="save"><?= $_save ?></button><table class="table"><tr><td><?= $_name ?></td><td><input class="form-control" name="name" value="<?= pv('name',$p) ?>" required></td></tr><tr><td>Local Address</td><td><input class="form-control" name="local-address" value="<?= pv('local-address',$p) ?>"></td></tr><tr><td>Remote Address</td><td><input class="form-control" name="remote-address" value="<?= pv('remote-address',$p) ?>"></td></tr><tr><td>Rate Limit</td><td><input class="form-control" name="rate-limit" value="<?= pv('rate-limit',$p) ?>"></td></tr><tr><td>DNS Server</td><td><input class="form-control" name="dns-server" value="<?= pv('dns-server',$p) ?>"></td></tr><tr><td><?= $_comment ?></td><td><input class="form-control" name="comment" value="<?= pv('comment',$p) ?>"></td></tr></table></form></div></div></div></div>
